'use strict';
window.FolioReports = (() => {
const esc = v => String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v);
function reportHTML(r,s){const a={...s.account,name:esc(s.account.name),kind:esc(s.account.kind),suffix:esc(s.account.suffix),risk:esc(s.account.risk)},m={...s.model,risk:esc(s.model.risk),id:esc(s.model.id)};const allocations=['Equities','Fixed income','Cash'];const rows=allocations.map((label,i)=>`<tr><td>${label}</td><td>${m.weights[i]}%</td><td>${money(a.value*m.weights[i]/100)}</td></tr>`).join('');const transition=allocations.map((label,i)=>{let diff=m.weights[i]-a.holdings[i];return `<tr><td>${label}</td><td>${a.holdings[i]}%</td><td>${m.weights[i]}%</td><td>${diff>0?'+':''}${diff} pp</td><td>${diff===0?'No change':diff>0?'Add ':'Reduce '}${diff===0?'':money(Math.abs(diff)*a.value/100)}</td></tr>`;}).join('');
 const sections={
 SAR:`<h2>Strategy allocation</h2><p>The selected model is <strong>${esc(m.name)}</strong>, with a ${m.risk.toLowerCase()} demo risk band. This view summarizes the proposed asset allocation.</p><table><thead><tr><th>Asset class</th><th>Target weight</th><th>Illustrative value</th></tr></thead><tbody>${rows}</tbody></table><h2>Account comparison</h2><p>The current and target allocations have ${a.holdings.reduce((sum,w,i)=>sum+Math.min(w,m.weights[i]),0)}% asset-class overlap. Overlap is calculated as the sum of the smaller weight in each asset class; it does not measure security-level overlap or predict returns.</p>`,
 TA:`<h2>Illustrative transition</h2><p>Changes below compare the fictional current allocation with the selected target model. Dollar amounts use the unchanged account value.</p><table><thead><tr><th>Asset class</th><th>Current</th><th>Target</th><th>Change</th><th>Illustrative adjustment</th></tr></thead><tbody>${transition}</tbody></table><p class="note">Percentage-point changes are shown as pp. No orders are created. Taxes, transaction costs, holdings restrictions, and market movements are excluded.</p>`,
 Proposal:`<h2>Portfolio proposal</h2><p>Prepare a discussion of <strong>${esc(m.name)}</strong> within <strong>${esc(s.program.name)}</strong> for ${a.name}.</p><table><thead><tr><th>Asset class</th><th>Proposed weight</th><th>Illustrative value</th></tr></thead><tbody>${rows}</tbody></table><h2>Advisor review before any action</h2><ul><li>Confirm objectives, horizon, liquidity needs, and client information.</li><li>Review investment-specific risks, restrictions, fees, and tax implications.</li><li>Complete the applicable suitability, authorization, and compliance processes.</li></ul><p>This is a fictional discussion document. No client acceptance or portfolio implementation has occurred.</p>`,
 CS:`<h2>Client snapshot</h2><p>${a.name} holds a fictional ${a.kind.toLowerCase()} account with a value of <strong>${money(a.value)}</strong> and a <strong>${a.risk.toLowerCase()}</strong> demo risk profile.</p><h2>Selected approach</h2><p>${esc(s.program.name)} · ${esc(m.name)} (${m.id})</p><table><thead><tr><th>Asset class</th><th>Target weight</th><th>Illustrative value</th></tr></thead><tbody>${rows}</tbody></table><h2>Conversation outcome</h2><p>Account, program, and model selections were carried forward without re-entry. Simplified demo validation passed before this report was created.</p>`};
 return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(r.name)} | Folio demo</title><style>body{font:16px/1.6 Arial,sans-serif;color:#192d42;background:#f1f5f8;margin:0;padding:32px}main{max-width:900px;margin:auto;background:white;padding:45px;border:1px solid #dce4ec}header{display:flex;justify-content:space-between;color:#087b70;font-weight:bold;font-size:14px}h1{font-size:32px;line-height:1.2;margin-top:35px}h2{font-size:19px;margin-top:30px}p{color:#4b6073}.meta{display:grid;grid-template-columns:1fr 1fr;gap:15px;padding:20px;background:#f3f7fa;font-size:14px}.meta span{display:block;color:#607489}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:12px 9px;border-bottom:1px solid #dce4ec;text-align:left}th{background:#f3f7fa}.note,footer{font-size:12px;color:#62758a}footer{border-top:1px solid #ddd;margin-top:32px;padding-top:18px}.toolbar{max-width:990px;margin:0 auto 16px;display:flex;justify-content:space-between;gap:10px;align-items:center;font-size:13px;color:#52677a}button{background:#112740;border:0;color:white;padding:10px 17px;border-radius:5px;cursor:pointer}@media print{body{padding:0;background:white}main{padding:15px;border:0;max-width:none}.toolbar{display:none}}@media(max-width:600px){body{padding:12px}main{padding:20px}.meta{grid-template-columns:1fr}table{font-size:11px}td,th{padding:8px 4px}h1{font-size:25px}}</style></head><body><div class="toolbar"><span>Fictional report · Snapshot from revision ${s.revision}</span><button onclick="window.print()">Print / Save as PDF</button></div><main><header><span>folio.</span><span>ILLUSTRATIVE REPORT</span></header><h1>${esc(r.name)}</h1><p>Generated from the selections in your portfolio conversation.</p><div class="meta"><div><span>Client / account</span>${a.name} · ••${a.suffix}</div><div><span>Advisory program</span>${esc(s.program.name)}</div><div><span>Model / strategy</span>${esc(m.name)} · ${m.id}</div><div><span>Portfolio value</span>${money(a.value)}</div><div><span>Generated</span>${esc(s.generated)}</div><div><span>Context revision</span>${s.revision}</div></div>${sections[r.id]}<footer>Independent concept prototype by Sukriti Priya. All accounts, models, allocations, and amounts are fictional. Not affiliated with Morgan Stanley. Not investment advice, a suitability assessment, or an executable instruction. This snapshot does not change when the conversation is updated.</footer></main></body></html>`;
}
return {render:reportHTML};
})();
